    messages: [...current.messages.slice(0, overlapCurrentIndex), ...context.messages.slice(firstOverlapInTail)],
    entryIds: [...current.entryIds.slice(0, overlapCurrentIndex), ...context.entryIds.slice(firstOverlapInTail)],
